"use client";
/* Brain, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Brain(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("brain"); }, []);
  return React.createElement("piix-sprite", { "name": "brain", ...piixAttrs(props) });
}

export default Brain;
